from pathlib import Path
import shutil

SOURCE = Path.home() / "Downloads"
RULES = {
    ".pdf": "Documents", ".docx": "Documents", ".xlsx": "Spreadsheets",
    ".csv": "Spreadsheets", ".jpg": "Images", ".png": "Images", ".zip": "Archives",
}
DRY_RUN = True

for item in SOURCE.iterdir():
    if not item.is_file():
        continue
    folder = SOURCE / RULES.get(item.suffix.lower(), "Other")
    target = folder / item.name
    if target.exists():
        target = folder / f"{item.stem}_copy{item.suffix}"
    print(f"{item.name} -> {folder.name}/")
    if not DRY_RUN:
        folder.mkdir(exist_ok=True)
        shutil.move(str(item), str(target))

import argparse

def build_parser():
    p = argparse.ArgumentParser(prog="wordstat", description="Count words in text")
    p.add_argument("words", nargs="+", help="words to count")
    p.add_argument("--min-length", type=int, default=1)
    p.add_argument("--upper", action="store_true", help="print in upper case")
    p.add_argument("--sort", choices=["alpha", "count"], default="alpha")
    return p

def main(argv=None):
    args = build_parser().parse_args(argv)
    counts = {}
    for w in args.words:
        if len(w) >= args.min_length:
            w = w.upper() if args.upper else w
            counts[w] = counts.get(w, 0) + 1
    key = (lambda kv: kv[0]) if args.sort == "alpha" else (lambda kv: -kv[1])
    for word, n in sorted(counts.items(), key=key):
        print(word, n)
    return 0

main(["to", "be", "or", "not", "to", "be", "--upper", "--sort", "count"])
